    op.execute(
        """
        UPDATE analysis_images
        SET entry_id = (
            SELECT ae.entry_id FROM analysis_entries ae
            WHERE ae.analysis_id = analysis_images.analysis_id AND ae.entry_type = 'GAP'
        )
        """
    )
    op.execute(
        """
        UPDATE analysis_images
        SET entry_id = (
            SELECT ae.entry_id FROM analysis_entries ae
            WHERE ae.analysis_id = analysis_images.analysis_id AND ae.entry_type = 'FLUSH'
        )
        WHERE entry_id IS NULL
        """
    )

