    op.drop_column('analysis_images', 'analysis_id')
    op.create_foreign_key(
        'analysis_images_entry_id_fkey',
        'analysis_images',
        'analysis_entries',
        ['entry_id'],
        ['entry_id'],
        ondelete='CASCADE',
    )
    op.create_index('ix_analysis_images_entry_id', 'analysis_images', ['entry_id'])


